import { db } from "@/lib/db";

export async function POST(request: Request) {
  const body = await request.json();
  const { title, seconds } = body;

  const telescope = await db.telescope.findUnique({
    where: { id: body.telescopeId },
  });

  if (!telescope) {
    return new Response("Telescope not found", { status: 404 });
  }

  if (seconds < 2 || seconds > 5400) {
    return new Response("Invalid seconds", { status: 400 });
  }

  if (telescope.exposureRecords.some((record) => record.title === title)) {
    return new Response("Duplicate title", { status: 409 });
  }

  const newExposureRecord = await db.exposureRecord.create({
    data: {
      title,
      seconds,
      telescopeId: body.telescopeId,
    },
  });

  return new Response(JSON.stringify(newExposureRecord), {
    status: 201,
  });
}

